    return describeDiscoveredResource(row,{handle,allowedOrigin:this.#trustedOrigins.has(row.origin),
      expiresAt:row.createdAt+this.#quoteTTL,remoteMcpPolicies:this.#mcpPolicies});
  }
  preview({handle,acceptIndex=0,input={}}={}){
    this.#running();
