  let url;
  try { url = new URL(value); } catch { fail('MCP_RESOURCE_INVALID'); }
  if (!['mcp:', 'http:', 'https:'].includes(url.protocol) || url.username || url.password || url.hash)
    fail('MCP_RESOURCE_INVALID');
