      if (!this.#closed) { this.#cache.delete(quote.quoteId); this.#cache.set(quote.quoteId, cached); }
      // At most 16 MiB, shared by every page read in this operator process.
      while (this.#cache.size > 8) this.#cache.delete(this.#cache.keys().next().value);
    }
    const chunk = cached.bytes.subarray(byteOffset, Math.min(byteOffset + maxBytes, saved.bytes));
    let text;
    if (byteOffset === 0 && chunk.length === saved.bytes) text = new TextDecoder('utf-8', {fatal:true}).decode(chunk);
    return {quoteId:quote.quoteId, representation:MCP_RESULT_REPRESENTATION,
      contentType:saved.contentType, bytes:saved.bytes, sha256:saved.sha256,
      byteOffset, returnedBytes:chunk.length, encoding:'base64', data:chunk.toString('base64'),
      ...(text === undefined ? {} : {text}),
      nextByteOffset:byteOffset + chunk.length < saved.bytes ? byteOffset + chunk.length : null};
  }
  async recover(quote) {
    this.#open(true);
    need(!this.#active.has(quote.quoteId), 'MCP_RESULT_CAPTURE_ACTIVE');
    const path = this.#destination(quote), manifestPath = this.#manifest(quote);
    let manifest;
    try {
      manifest = parse(await readPrivateResultSource(manifestPath, {maxBytes:MANIFEST_BYTES}));
      need(manifest.schema === MANIFEST_SCHEMA, 'MCP_RESULT_METADATA_INVALID');
    } catch (error) { if (error.code !== 'ENOENT') throw error; }
    let restored = manifest ? completedQuote(quote, manifest.quote) : structuredClone(quote);
    const bytes = await readPrivateResultSource(path), result = await retainedResult(restored, bytes);
    requireOutcome(restored, result);
    if (quote.result?.content) {
      await retainedResult(quote, bytes);
      // A previous confirmed completion must not be downgraded by older metadata.
      if (['CONFIRMED_BY_SERVER','FREE_SUCCESS'].includes(quote.status)) restored = structuredClone(quote);
    }
    const prior = manifest?.quote.result.responseFile ?? quote.result?.responseFile;
    if (prior) {
      this.#bound(quote, prior);
      if (prior.status === 'SAVED') need(prior.bytes === bytes.length && prior.sha256 === sha(bytes), 'MCP_RESULT_FILE_CHANGED');
    }
    const saved = {...this.#reservation(quote), ...prior, status:'SAVED', path, bytes:bytes.length,
      sha256:sha(bytes), manifestStatus:manifest ? 'SAVED' : 'MISSING',
      capturedAt:prior?.capturedAt ?? new Date().toISOString(), recovered:true};
    restored.result = {...restored.result, content:mcpResultContent(result), responseFile:saved,
      ...(restored.result.paidAttempted ? {paymentResponse:paymentResponseSummary(result?._meta?.['x402/payment-response'])} : {})};
    retainPaymentObservation(restored, quote);
    if (!manifest) {
      let writer;
      try {
        writer = await prepareBuyerResponseFile({destination:manifestPath,
          maxBytes:MANIFEST_BYTES, expectedContentType:'application/json'});
        saved.manifestStatus = 'SAVED';
        await manifestBytes(restored, saved, writer); await syncDirectory(this.#root);
      } catch (error) { saved.manifestStatus = 'SAVE_FAILED'; saved.manifestError = error.code ?? 'MCP_RESULT_METADATA_FAILED'; }
      finally { await writer?.abort(); }
    }
    return restored;
  }
  async import(quote, bytes) {
    this.#open(true);
    need(!['PREVIEWED','APPROVAL_PENDING','EXECUTING','CANCEL_REQUESTED'].includes(quote.status), 'MCP_RESULT_NOT_READY');
    const result = await retainedResult(quote, bytes);
    if (quote.result?.responseFile?.status === 'SAVED') { await this.file(quote).verify(); return {saved:quote.result.responseFile}; }
    return {capture:await this.prepare(quote), result};
  }
  async close() {
    if (this.#closed) return;
    this.#closed = true; this.#cache.clear();
    await Promise.allSettled([...this.#active.values()].map(async entry => (await entry.promise).abort()));
  }
}

/** Trusted host import of a previously returned native result; no provider call. */
export async function importRetainedMcpResult({quoteStore, resultStore, quoteId, bytes, completion}) {
  let quote = quoteStore.load().find(record => record.quoteId === key(quoteId));
  need(quote, 'QUOTE_UNKNOWN');
  if (completion !== undefined) {
    const restored = completedQuote(quote, completion), result = await retainedResult(restored, bytes);
    requireOutcome(restored, result);
    if (quote.result?.content) await retainedResult(quote, bytes);
    if (!quote.result?.content || !RESULT_STATES.has(quote.status)) {
      // The full original host completion repairs an older database snapshot.
      // No approval, signer, merchant or ledger is called by this import.
      quote = retainPaymentObservation(restored, quote);
      quote.result.content = mcpResultContent(result);
      delete quote.result.responseFile;
      quote.updatedAt = Date.now(); quoteStore.save(quote);
    }
  }
  const imported = await resultStore.import(quote, bytes);
  if (imported.saved) return structuredClone(imported.saved);
  const persist = () => { quote.updatedAt = Date.now(); quoteStore.save(quote); };
  try {
    quote.result.responseFile = imported.capture.reservation; persist();
    quote.result.responseFile = {...await imported.capture.save(imported.result), imported:true}; persist();
    return structuredClone(quote.result.responseFile);
  } catch (error) {
    quote.result.responseFile = {...imported.capture.reservation, status:'SAVE_FAILED',
      error:error.code ?? 'MCP_RESULT_SAVE_FAILED', partialPath:error.partialPath ?? null};
    persist(); throw error;
  } finally { await imported.capture.abort(); }
}

export async function recoverRetainedMcpResult({quoteStore, resultStore, quoteId}) {
  const original = quoteStore.load().find(record => record.quoteId === key(quoteId));
  need(original, 'QUOTE_UNKNOWN');
  const quote = await resultStore.recover(original);
  quote.updatedAt = Date.now(); quoteStore.save(quote);
  return {quoteId:quote.quoteId, status:quote.status, responseFile:structuredClone(quote.result.responseFile)};
}

/** MIT. Operator-owned loopback MCP workspace; credentials never arrive over MCP. */
import { createServer } from 'node:http';
import { isAbsolute, join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { McpPaidToolBroker, createMcpHttpHandler } from './agent-server.mjs';
import { createOperatorConsoleHandler } from './operator-console.mjs';
import { loadOAuthResourceHost } from './oauth-host.mjs';

export async function startMcpWorkspace({ environment = process.env, oauthFetchImpl, operatorAdapter } = {}) {
  const discoveryUrl = environment.BAZAAR_DISCOVERY_URL;
  const bearerToken = environment.MCP_ACCESS_TOKEN;
  const oauthConfigPath = environment.MCP_OAUTH_CONFIG;
  if (!discoveryUrl || (!bearerToken && !oauthConfigPath))
    throw new TypeError('Configure BAZAAR_DISCOVERY_URL and either MCP_ACCESS_TOKEN or MCP_OAUTH_CONFIG.');
  const modulePath = environment.MCP_OPERATOR_MODULE;
  const directory = environment.MCP_STATE_DIR;
  if (modulePath && (!isAbsolute(modulePath) || !directory))
    throw new TypeError('An operator module requires an absolute MCP_OPERATOR_MODULE and durable MCP_STATE_DIR.');
  if (operatorAdapter !== undefined && (modulePath || !directory || !operatorAdapter || typeof operatorAdapter !== 'object'))
    throw new TypeError('A trusted in-process operator requires durable MCP_STATE_DIR and no MCP_OPERATOR_MODULE.');
  const allowedResourceOrigins = (environment.PAID_RESOURCE_ORIGINS ?? '').split(',').map(value => value.trim()).filter(Boolean);
  const allowedClientOrigins = (environment.MCP_CLIENT_ORIGINS ?? '').split(',').map(value => value.trim()).filter(Boolean);
  const port = Number(environment.MCP_PORT ?? 3210);
  if (!Number.isSafeInteger(port) || port < 0 || port > 65535) throw new RangeError('Invalid MCP_PORT');
  const timeoutMs = Number(environment.MCP_PROVIDER_TIMEOUT_MS ?? 8000);
  if (!Number.isSafeInteger(timeoutMs) || timeoutMs < 1 || timeoutMs > 300000)
    throw new RangeError('MCP_PROVIDER_TIMEOUT_MS must be 1..300000');
  let quoteStore, resultStore, broker, server, operator = operatorAdapter, address, access;
  try {
    access = await loadOAuthResourceHost({configPath:oauthConfigPath,bearerToken,fetchImpl:oauthFetchImpl});
    if (directory) {
      const { SqliteQuoteStore } = await import('./quote-store.mjs');
      quoteStore = new SqliteQuoteStore({ directory });
      const {McpResultStore} = await import('./result-store.mjs');
      resultStore = new McpResultStore({directory:join(quoteStore.directory,'results')});
    }
    if (modulePath) {
      // Executable trusted host configuration, never a path from MCP or discovery.
      operator = await import(pathToFileURL(modulePath).href);
    }
    if (operator) {
      // A native launcher may supply its already-open trusted operator. Never
      // accept this host-only callback object from an MCP request or environment.
      const pays = typeof operator.approve === 'function' && typeof operator.signPayment === 'function';
      const readsOnly = operator.approve === undefined && operator.signPayment === undefined &&
        (typeof operator.reconcilePayment === 'function' || typeof operator.spendingStatus === 'function');
      if ((!pays && !readsOnly) ||
          (operator.reconcilePayment !== undefined && typeof operator.reconcilePayment !== 'function') ||
          (operator.spendingStatus !== undefined && typeof operator.spendingStatus !== 'function') ||
          (operator.close !== undefined && typeof operator.close !== 'function') ||
          (operator.agentCommerce !== undefined && typeof operator.agentCommerce !== 'function'))
        throw new TypeError('Export paired approve/signPayment functions, reconciliation or spending inspection functions, or both.');
    }
    broker = new McpPaidToolBroker({ discoveryUrl, allowedResourceOrigins, quoteStore, resultStore, timeoutMs,
      ...(operator ? { ...(operator.signPayment ? {approve:operator.approve,signPayment:operator.signPayment} : {}),
        reconcilePayment:operator.reconcilePayment ?? null,spendingStatus:operator.spendingStatus ?? null,
        agentCommerce: operator.agentCommerce ?? null,
        ...(operator.fetchImpl === undefined ? {} : {fetchImpl:operator.fetchImpl}),
        remoteMcpPolicies: operator.remoteMcpPolicies ?? [] } : {}) });
    let handler;
    server = createServer((request, response) => {
      if (handler) return handler(request, response);
      response.writeHead(503); response.end();
    });
    await new Promise((done, reject) => {
      server.once('error', reject);
      server.listen(port, '127.0.0.1', () => { server.removeListener('error', reject); done(); });
    });
    address = `http://127.0.0.1:${server.address().port}`;
    handler = createOperatorConsoleHandler(access.wrap(createMcpHttpHandler(broker, {
      ...access.transportOptions, allowedClientOrigins: [...new Set([...allowedClientOrigins, address])],
    })), {origin: address});
  } catch (failure) {
    server?.close();
    try {
      if (broker) await broker.close({ graceMs: 0 });
      else { try { await resultStore?.close(); } finally { quoteStore?.close(); } }
    }
    catch { /* report the original startup failure after closing operator resources */ }
    finally {
      try { await access?.close(); } catch { /* preserve original failure */ }
      try { await operator?.close?.(); } catch { /* preserve original failure */ }
    }
    throw failure;
  }
  let closing;
  return {
    broker, server, address, consoleUrl: `${address}/console/`, authorization:access.describe(),
    durable: Boolean(quoteStore), paymentAdapterConnected: typeof operator?.signPayment === 'function',
    paymentReconciliationConnected: typeof operator?.reconcilePayment === 'function',
    aggregateSpendingConnected: typeof operator?.spendingStatus === 'function',
    close() {
      if (closing) return closing;
      closing = (async () => {
        const stopped = new Promise(done => server.close(done));
        let failure;
        try { await access.close(); } catch (error) { failure = error; }
        try { await broker.close(); } catch (error) { failure ??= error; }
        finally {
          server.closeAllConnections(); await stopped;
          try { await operator?.close?.(); } catch (error) { failure ??= error; }
        }
        if (failure) throw failure;
      })();
      return closing;
    },
  };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    const args = process.argv.slice(2);
    if (args.length === 1 && ['--help', '-h'].includes(args[0])) {
      process.stdout.write(`Usage: node serve.mjs\n\nStart the original loopback MCP buyer and browser console.\nRequired: BAZAAR_DISCOVERY_URL and either MCP_ACCESS_TOKEN (at least 24 characters)\nor an absolute MCP_OAUTH_CONFIG path. The two access modes are exclusive.\nOAuth uses the existing issuer, explicit operator subjects and original tool scopes.\nMCP_STATE_DIR retains original quotes and complete native results.\nMCP_PORT defaults to 3210; 0 selects an available port.\nOpen the printed http://127.0.0.1:PORT/console/ URL and enter the same access token.\nPAID_RESOURCE_ORIGINS selects the merchant origins permitted for quotes.\nMCP_CLIENT_ORIGINS allows additional original MCP client origins.\nPaid execution requires an absolute trusted MCP_OPERATOR_MODULE and MCP_STATE_DIR.\nThat host module owns independent approval and signing; the browser cannot approve for it.\nMCP_PROVIDER_TIMEOUT_MS: 1..300000, default 8000.\nGuides: README.md, CONSOLE.md, REMOTE_MCP.md, RESULTS.md, OAUTH_RESOURCE.md.\n`);
    } else {
      if (args.length) throw new TypeError('This launcher uses environment configuration. Use --help for its settings.');
      const workspace = await startMcpWorkspace();
      process.stderr.write(`Stellar MCP workspace at ${workspace.address}; history ${workspace.durable ? 'durable' : 'in memory'}; payment adapter ${workspace.paymentAdapterConnected ? 'connected, independent approval required' : 'not connected'}.\n`);
      process.stderr.write(`Buyer console: ${workspace.consoleUrl}\n`);
      let stopping = false;
      const stop = async () => {
        if (stopping) return; stopping = true;
        try { await workspace.close(); }
        catch (failure) { process.stderr.write(`Workspace close failed (${failure.code ?? 'OPERATOR_ERROR'}). Preserve its state directory.\n`); process.exitCode = 2; }
      };
      process.once('SIGINT', stop); process.once('SIGTERM', stop);
    }
  } catch (failure) {
    process.stderr.write(`Workspace startup failed: ${failure.code ?? 'CONFIGURATION_ERROR'}: ${failure.message}\n`);
    process.exitCode = 2;
  }
}

#!/usr/bin/env node
/** MIT. Subprocess transport for the maintained MCP workspace and tool handler. */
import { randomBytes } from 'node:crypto';
import { request } from 'node:http';
import { Console } from 'node:console';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { MCP_VERSION, MAX_MCP_REQUEST_BYTES, MAX_MCP_REPLY_BYTES } from './http-tools.mjs';

// A merchant-supplied workspace owns its runtime. Load the paid buyer only when
// the default buyer transport is actually selected.
async function startDefaultWorkspace(options) {
  const { startMcpWorkspace } = await import('./serve.mjs');
  return startMcpWorkspace(options);
}

const MAX_FRAME_BYTES = 128 * 1024;
const MAX_REPLY_BYTES = 8 * 1024 * 1024;
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const validId = value => typeof value === 'string' || Number.isSafeInteger(value);
const rpcError = (id, code, message) => ({ jsonrpc: '2.0', id, error: { code, message } });
const failure = code => Object.assign(new Error(code), { code });

/** One request, one original handler invocation. The private HTTP hop never retries. */
function forward(endpoint, token, rpc, signal, maximumReplyBytes = MAX_REPLY_BYTES) {
  const body = Buffer.from(JSON.stringify(rpc));
  return new Promise((done, reject) => {
    const req = request(endpoint, {
      method: 'POST', signal,
      headers: {
        authorization: `Bearer ${token}`, 'content-type': 'application/json',
        accept: 'application/json, text/event-stream', 'mcp-protocol-version': MCP_VERSION,
        'content-length': body.byteLength,
      },
    }, res => {
      let size = 0;
      const chunks = [];
      res.on('data', chunk => {
        size += chunk.byteLength;
        if (size > maximumReplyBytes) res.destroy(failure('MCP_LOCAL_REPLY_TOO_LARGE'));
        else chunks.push(chunk);
      });
      res.once('error', reject);
      res.once('end', () => {
        if (res.statusCode === 202 && size === 0) return done(null);
        try {
          const reply = JSON.parse(new TextDecoder('utf-8', { fatal: true })
            .decode(Buffer.concat(chunks, size)));
          if (!plain(reply) || reply.jsonrpc !== '2.0' || reply.id !== rpc.id ||
              Object.hasOwn(reply, 'result') === Object.hasOwn(reply, 'error'))
            throw failure('MCP_LOCAL_REPLY_INVALID');
          done(reply);
        } catch { reject(failure('MCP_LOCAL_REPLY_INVALID')); }
      });
    });
    req.once('error', reject);
    req.end(body);
  });
}

/**
 * A trusted embedding can supply its existing workspace factory. It receives the
 * same environment as startMcpWorkspace, with an ephemeral loopback port and a
 * transport-only bearer generated here. It must return {address, close} and may
 * declare maxRequestBytes (up to 65 MiB) and maxReplyBytes (up to 128 MiB)
 * for its original HTTP handler. Defaults remain 128 KiB and 8 MiB.
 * The default factory owns the original broker, approval adapter and quote store.
 */
export async function startMcpStdio({
  environment = process.env, input = process.stdin, output = process.stdout,
  startWorkspace = startDefaultWorkspace, cancelRequest = null, maxConcurrent = 32,
  diagnostic = code => process.stderr.write(`Stellar MCP stdio: ${code}\n`),
} = {}) {
  if (!Number.isSafeInteger(maxConcurrent) || maxConcurrent < 1 || maxConcurrent > 256)
    throw new RangeError('maxConcurrent must be an integer from 1 to 256');
  if (typeof startWorkspace !== 'function' || typeof diagnostic !== 'function' ||
      (cancelRequest !== null && typeof cancelRequest !== 'function'))
    throw new TypeError('Workspace and diagnostic hooks must be functions');
  const token = randomBytes(32).toString('hex');
  const workspace = await startWorkspace({ environment: {
    ...environment, MCP_ACCESS_TOKEN: token, MCP_PORT: '0', MCP_CLIENT_ORIGINS: '',
  } });
  let endpoint, maxFrameBytes, maxReplyBytes;
  try {
    maxFrameBytes = workspace.maxRequestBytes ?? MAX_FRAME_BYTES;
    if (!Number.isSafeInteger(maxFrameBytes) || maxFrameBytes < 1 || maxFrameBytes > MAX_MCP_REQUEST_BYTES)
      throw failure('MCP_WORKSPACE_REQUEST_LIMIT_INVALID');
    maxReplyBytes = workspace.maxReplyBytes ?? MAX_REPLY_BYTES;
    if (!Number.isSafeInteger(maxReplyBytes) || maxReplyBytes < 1 || maxReplyBytes > MAX_MCP_REPLY_BYTES)
      throw failure('MCP_WORKSPACE_REPLY_LIMIT_INVALID');
