            if (line.length) await acceptFrame(line);
          }
          chunks = []; size = 0; oversized = false; offset = newline + 1;
        }
      }
      if (phase !== 'CLOSING' && (size || oversized))
        await emit(rpcError(null, -32700, 'Incomplete newline-delimited message at end of input'));
    } catch (error) {
