const fields=(value,allowed,required=allowed)=>check(plain(value)&&Object.keys(value).every(key=>allowed.includes(key))&&
  required.every(key=>Object.hasOwn(value,key)),'CLIENT_RECEIVE_FIELDS_INVALID');
