function parse(raw) {
  try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(raw)); }
  catch { throw new InputError('PAID_FILE_JSON_INVALID'); }
}
const json = async path => parse(await bytes(path));
