      try {const value=await json(join(root,name));need(value.schema===SCHEMA&&value.directory===directory&&
        value.recordSha256===name.slice(0,-5),'RUNBOOK_RECOVERY_SELECTION_CHANGED');records.push(value);}
      catch(error){records.push({recordSha256:name.slice(0,-5),error:codeOf(error)});}
    }
    return records.sort((a,b)=>(b.createdAt??'').localeCompare(a.createdAt??''));
  }
  return {inspect,snapshot,history};
}

async function inspectSnapshot({record,map}) {
  const profile=record.application;
  need(record.schema===COLLECTION&&profile?.schema===SCHEMA&&profile.stateRoot===record.plan.stateRoot&&
    HASH.test(profile.reviewSha256??'')&&profileDigest(profile)===profile.reviewSha256&&
    Array.isArray(profile.runs)&&profile.runs.length<=512&&Array.isArray(profile.configurations)&&
    profile.configurations.length<=4096&&Array.isArray(profile.operators)&&profile.operators.length<=64,
    'RUNBOOK_RECOVERY_APPLICATION_RECORD_INVALID');
  const root=profile.stateRoot;
  for(const path of [profile.directory,profile.configsDirectory,...profile.operators]) {
    canonical(path);need(inside(root,path),'RUNBOOK_RECOVERY_DEPENDENCY_OUTSIDE_ROOT');
  }
  need(hash(await bytes(map(join(profile.directory,'workspace.json'))))===profile.workspaceSha256,
    'RUNBOOK_RECOVERY_WORKSPACE_IDENTITY_CHANGED');
  const workspace=await json(map(join(profile.directory,'workspace.json')));
  need(workspace.schema===WORKSPACE&&workspace.directory===profile.directory&&
    workspace.configsDirectory===profile.configsDirectory,'RUNBOOK_RECOVERY_WORKSPACE_IDENTITY_CHANGED');
  need(same([...profile.operators].sort(),[record.plan,...record.plan.operators].map(item=>item.directory).sort()),
    'RUNBOOK_RECOVERY_ORIGINAL_OPERATOR_REQUIRED');
  for(const run of profile.runs) {
    canonical(run.directory);need(inside(root,run.directory),'RUNBOOK_RECOVERY_DEPENDENCY_OUTSIDE_ROOT');
    const plan=await readPlan(run.directory,{storageDirectory:map(run.directory)});
    need(plan.id===run.planId&&runbookPlanDigest(plan)===run.planSha256,'RUNBOOK_RECOVERY_RUN_CHANGED');
    need(same(plan.operations.map(row=>({id:row.id,intentId:row.intentId,configSha256:row.config.sha256})),
      run.operations.map(({id,intentId,configSha256})=>({id,intentId,configSha256}))), 'RUNBOOK_RECOVERY_RUN_CHANGED');
  }
  for(const entry of profile.configurations) {
    canonical(entry.path);need(inside(root,entry.path)&&profile.operators.includes(entry.operator)&&HASH.test(entry.sha256),
      'RUNBOOK_RECOVERY_CONFIGURATION_CHANGED');
    need(hash(await bytes(map(entry.path),65536))===entry.sha256,'RUNBOOK_RECOVERY_CONFIGURATION_CHANGED');
  }
}
export async function verifyRunbookRecovery(options,context={}) {
  const result=await verifyWorkspaceRecovery(options,{...context,inspectSnapshot});
  return {...result,bundle:canonical(options.bundle)};
}
export async function restoreRunbookRecovery(options,context={}) {
  const restored=await restoreWorkspaceRecovery(options,{...context,inspectSnapshot});
  const {openRunbookWorkspace}=await import('./workspace-model.mjs');
  let model,reopened=null,reopenError=restored.nativeReopenErrors?.length?'RUNBOOK_RECOVERY_NATIVE_REOPEN_FAILED':null;
  try {
    model=await openRunbookWorkspace({directory:restored.application.directory});
    const state=await model.state();need(state.errors.length===0,'RUNBOOK_RECOVERY_REOPEN_FAILED');
    for(const run of restored.application.runs) {
      const current=await model.run(run.id);
      need(runbookPlanDigest(current.state.plan)===run.planSha256&&!current.state.executionLock,
        'RUNBOOK_RECOVERY_REOPEN_FAILED');
    }
    reopened={directory:model.directory,acquisitions:state.acquisitions.length,
      requests:state.intake.requests.length,configurations:state.configurations.filter(item=>item.valid).length};
  } catch(error){reopenError??=codeOf(error);}
  finally {try{await model?.close();}catch(error){reopenError??=codeOf(error);}}
  return {...restored,bundle:canonical(options.bundle),reopened,reopenError,executionStarted:false};
}

// MIT. Offline industrial operator report; no scripts, external resources or forms.
const escape = value => String(value ?? '').replace(/[&<>"']/g, character =>
  ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const code = value => `<code>${escape(value ?? '—')}</code>`;
const json = value => escape(JSON.stringify(value, null, 2));

function nextAction(row) {
  if (row.integrity !== 'UNCHANGED') return 'Restore the recorded config or body snapshot from its original input, or initialize a separate reviewed plan. Existing attempts remain recorded.';
  if (row.state === 'UNATTEMPTED') return row.lastError ?
    'Resolve the displayed local setup problem, then execute this runbook to continue this untouched operation.' :
    'Execute this runbook when ready. The original buyer obtains fresh seller terms and uses its original terminal approval.';
  if (row.state === 'INTERRUPTED_NO_RESULT') return 'Use recover to import any complete original SF88 output. Inspect the retained output, native evidence and original governor reservation for this intent before selecting any further action.';
  if (row.state === 'NOT_LAUNCHED') return 'The native process was not launched. Fix the launch error; the saved native config remains available for a separately selected original SF88 operation. This runbook keeps its recorded attempt.';
  if (row.state === 'NO_COMPLETE_NATIVE_RESULT') return 'Inspect the original stdout/stderr, evidence directory and governor ledger using the same intent ID. The runbook will continue untouched jobs without purchasing this operation again.';
  const summary = row.result?.summary;
  if (summary?.error || summary?.evidenceError || summary?.responseFile?.status === 'FAILED')
    return 'Use the original buyer/evidence error and any saved or partial output below to resolve this operation. Other untouched jobs can continue. A file failure does not cancel a payment.';
  return row.accounting?.finalized?'Use the returned resource and retained original accounting receipt. A later accounting refresh reuses the same original ledger.':
    'Refresh accounting in this acquisition or with the finalize command. Select this request’s existing original operator workspace if it was not received here.';
}

function accounting(row) {
  const value=row.accounting,final=value?.finalized;
  if(!value)return '';
  return `<section class="result"><h3>Original accounting</h3><dl class="terms"><div><dt>Latest check</dt><dd>${code(value.outcome)} · ${escape(value.checkedAt??'Not checked')}</dd></div><div><dt>Original operator</dt><dd>${code(value.workspace)}</dd></div><div><dt>Finalized actual atomic units</dt><dd>${final?code(final.actualAtomicUnits):'Awaiting original finalization'}</dd></div><div><dt>Receipt</dt><dd>${code(final?.receipt)}</dd></div>${final?`<div><dt>Finalized request digest</dt><dd>${code(final.requestSha256)}</dd></div><div><dt>Receipt retained at</dt><dd>${escape(final.completedAt)}</dd></div>`:''}</dl>${value.lastError?`<p class="notice">Latest accounting condition: ${code(value.lastError)}. An earlier finalized receipt remains included when present.</p>`:''}${value.outcome==='NO_PAYMENT_REQUIRED'?'<p>This is the original unsigned response; it carries no ledger receipt or actual payment amount.</p>':''}</section>`;
}

/** Accounting CSV is a view of existing original results, one operation per row. */
export function renderAccountingCSV(state) {
  const cell=value=>{
    let text=String(value??'');
    if(/^[\s]*[=+@-]/.test(text))text="'"+text;
    return '"'+text.replaceAll('"','""')+'"';
  };
  const rows=[['operation_id','label','intent_id','network','asset','request_ceiling_atomic',
    'finalized_actual_atomic','receipt','finalized_request_sha256','receipt_completed_at',
    'latest_accounting_outcome','latest_check_at','latest_error','buyer_state','buyer_status','delivery_status']];
  for(const row of state.operations){const value=row.accounting,final=value?.finalized;
    rows.push([row.id,row.label,row.intentId,row.acceptedCaps.network,row.acceptedCaps.asset,row.acceptedCaps.maxAtomic,
      final?.actualAtomicUnits,final?.receipt,final?.requestSha256,final?.completedAt,value?.outcome,value?.checkedAt,
      value?.lastError,row.state,row.result?.summary?.status,row.result?.summary?.responseFile?.status]);}
  return rows.map(row=>row.map(cell).join(',')).join('\r\n')+'\r\n';
}

function accountingTotals(state) {
  if(!state.accounting)return '';
  return `<section class="panel"><h2>Accounting and receipts</h2><p class="muted">${escape(state.accounting.meaning)}</p><div class="table"><table><thead><tr><th>Network / asset</th><th>Finalized atomic units</th><th>Finalized</th><th>Unsigned</th><th>Unresolved</th><th>Untouched</th></tr></thead><tbody>${state.accounting.groups.map(group=>`<tr><td>${code(group.network)}<br>${code(group.asset)}</td><td>${code(group.finalizedActualAtomic)}</td><td>${group.finalizedOperations}</td><td>${group.unsignedOperations}</td><td>${group.unresolvedOperations}</td><td>${group.unattemptedOperations}</td></tr>`).join('')}</tbody></table></div></section>`;
}

function job(row) {
  const summary = row.result?.summary, delivery = summary?.responseFile;
  const terms = row.acceptedCaps;
  return `<article id="${escape(row.id)}">
  <div class="heading"><div><p class="eyebrow">${escape(row.id)} · ${escape(row.state)}</p><h2>${escape(row.label)}</h2></div><span class="state">${escape(row.integrity)}</span></div>
  <p class="resource">${code(row.method)} ${code(row.url)}</p>
  <dl class="terms"><div><dt>Intent</dt><dd>${code(row.intentId)}</dd></div><div><dt>Actor / service</dt><dd>${code(row.actor)} / ${code(row.service)}</dd></div><div><dt>Network / scheme</dt><dd>${code(terms.network)} / ${code(terms.scheme)}</dd></div><div><dt>Maximum atomic units</dt><dd>${code(terms.maxAtomic)}</dd></div><div><dt>Asset</dt><dd>${code(terms.asset)}</dd></div><div><dt>Recipient</dt><dd>${code(terms.payTo)}</dd></div><div><dt>Timeout ceiling</dt><dd>${terms.maxTimeoutSeconds === undefined ? 'No additional caller ceiling' : escape(terms.maxTimeoutSeconds) + ' seconds'}</dd></div><div><dt>Payment flow</dt><dd>${escape(terms.paymentFlow ?? 'Original buyer selection')}</dd></div><div><dt>Request body</dt><dd>${row.body ? `${row.body.bytes.toLocaleString('en-US')} bytes · ${code(row.body.sha256)}` : 'Absent'}</dd></div><div><dt>Output destination</dt><dd>${code(row.responseFile?.destination)}</dd></div></dl>
  <p class="action">${escape(nextAction(row))}</p>
  ${row.lastError ? `<p class="notice">Local setup: ${code(row.lastError.code)}</p>` : ''}
  ${row.integrityError ? `<p class="notice">Input: ${code(row.integrityError)}</p>` : ''}
  ${summary ? `<div class="result"><h3>Original buyer result</h3><dl class="terms"><div><dt>Buyer / HTTP status</dt><dd>${code(summary.status)} / ${code(summary.httpStatus)}</dd></div><div><dt>Native process exit</dt><dd>${row.result.recovered ? 'Recovered result; process exit not observed' : code(row.result.exitCode)}</dd></div><div><dt>Local file</dt><dd>${code(delivery?.status ?? 'NOT_REQUESTED')}${delivery?.bytes !== undefined ? ` · ${escape(delivery.bytes)} bytes` : ''}</dd></div><div><dt>Native evidence</dt><dd>${code(summary.evidencePath)}</dd></div><div><dt>Saved output</dt><dd>${code(delivery?.path ?? delivery?.destination)}</dd></div><div><dt>Partial output</dt><dd>${code(delivery?.partialPath)}</dd></div></dl>
  ${row.downloadName && delivery?.status === 'SAVED' ? `<p><a href="downloads/${encodeURIComponent(row.downloadName)}" download="${escape(row.downloadName)}">Download ${escape(row.downloadName)}</a></p>` : ''}
  <details><summary>Original SF88 summary</summary><pre>${json(summary)}</pre></details></div>` : ''}
  ${accounting(row)}
  <details><summary>Input lineage and attempt records</summary><pre>${json({sourceConfig:row.sourceConfig, snapshot:row.config, body:row.body, headers:row.headers, started:row.started, result:row.result ? {...row.result, summary:undefined} : null})}</pre></details>
  </article>`;
}

